using namespace std;long json_limit=31*1024*1024;chrono::steady_clock::time_point started;
void tick(){assert(chrono::duration<double>(chrono::steady_clock::now()-started).count()<50);}
void readp(istream&f,fmpz_poly_t p){long n;f>>n;assert(f&&n>=0);fmpz_t c;fmpz_init(c);for(long i=0;i<n;i++){long j;string s;f>>j>>s;assert(j>=0&&!fmpz_set_str(c,s.c_str(),10));fmpz_poly_set_coeff_fmpz(p,j,c);}fmpz_clear(c);}
void jp(ostream&o,const fmpz_poly_t p){o<<'[';bool first=true;fmpz_t c;fmpz_init(c);for(long j=fmpz_poly_degree(p);j>=0;j--){fmpz_poly_get_coeff_fmpz(c,p,j);if(fmpz_is_zero(c))continue;if(!first)o<<',';first=false;char*s=fmpz_get_str(nullptr,10,c);o<<'['<<j<<",\""<<s<<"\"]";flint_free(s);}fmpz_clear(c);o<<']';assert(o.tellp()<json_limit);}
long decimal_bytes(const fmpz_poly_t p){long z=0;for(long i=0;i<fmpz_poly_length(p);i++)z+=30+(fmpz_bits(p->coeffs+i)*30103+99999)/100000;return z;}
int main(int argc,char**argv){assert(argc==5);started=chrono::steady_clock::now();ifstream f(argv[1]);fmpz_poly_mat_t A,B,X,check;fmpz_poly_mat_init(A,17,17);fmpz_poly_mat_init(B,17,7);fmpz_poly_mat_init(X,17,7);fmpz_poly_mat_init(check,17,7);for(int i=0;i<17;i++)for(int j=0;j<17;j++)readp(f,fmpz_poly_mat_entry(A,i,j));for(int i=0;i<17;i++)for(int j=0;j<7;j++)readp(f,fmpz_poly_mat_entry(B,i,j));fmpz_poly_t expected,R,den;fmpz_poly_init(expected);fmpz_poly_init(R);fmpz_poly_init(den);readp(f,expected);readp(f,R);assert(fmpz_poly_degree(R)==46);string extra;assert(!(f>>extra));assert(fmpz_poly_mat_solve_fflu(X,den,A,B));assert(!fmpz_poly_is_zero(den));
 long checkpoint_bytes=0;{ofstream ck(argv[3]);ck<<"{\"solver_denominator\":";jp(ck,den);ck<<",\"all119_solution_cofactors\":[";for(int i=0;i<17;i++){if(i)ck<<',';ck<<'[';for(int j=0;j<7;j++){if(j)ck<<',';jp(ck,fmpz_poly_mat_entry(X,i,j));}ck<<']';}ck<<"]}\n";checkpoint_bytes=ck.tellp();}json_limit=30*1024*1024-checkpoint_bytes;assert(json_limit>1024*1024);cerr<<"ALL119_CHECKPOINT_SAVED bytes="<<checkpoint_bytes<<" remaining_limit="<<json_limit<<"\n";tick();
 fmpq_poly_t qden,qexpected,qcheck;fmpq_poly_init(qden);fmpq_poly_init(qexpected);fmpq_poly_init(qcheck);fmpq_poly_set_fmpz_poly(qden,den);fmpq_poly_set_fmpz_poly(qexpected,expected);fmpq_t ratio;fmpq_init(ratio);fmpz_t dlead,elead;fmpz_init(dlead);fmpz_init(elead);fmpz_poly_get_coeff_fmpz(dlead,den,fmpz_poly_degree(den));fmpz_poly_get_coeff_fmpz(elead,expected,fmpz_poly_degree(expected));fmpq_set_fmpz_frac(ratio,dlead,elead);fmpq_canonicalise(ratio);fmpq_poly_scalar_mul_fmpq(qcheck,qexpected,ratio);assert(fmpq_poly_equal(qcheck,qden));
 fmpz_poly_mat_mul(check,A,X);fmpz_poly_t rhs;fmpz_poly_init(rhs);for(int i=0;i<17;i++)for(int j=0;j<7;j++){fmpz_poly_mul(rhs,den,fmpz_poly_mat_entry(B,i,j));assert(fmpz_poly_equal(rhs,fmpz_poly_mat_entry(check,i,j)));}cerr<<"ALL119_AX_EQUALS_DEN_B_PASS\n";
 long totalcoeff=0;for(int i=0;i<17;i++)for(int j=0;j<7;j++)totalcoeff+=fmpz_poly_length(fmpz_poly_mat_entry(X,i,j));assert(totalcoeff<150000);int si=-1,sj=-1;fmpz_poly_t q;fmpz_poly_init(q);for(int j=0;j<7&&sj<0;j++)for(int i=0;i<17;i++){if(!fmpz_poly_divides(q,fmpz_poly_mat_entry(X,i,j),R)){si=i;sj=j;break;}}
 bool gcd1=false,bezsaved=false;fmpq_poly_t entryq,Rq,Gq,Sq,Tq;fmpq_poly_init(entryq);fmpq_poly_init(Rq);fmpq_poly_init(Gq);fmpq_poly_init(Sq);fmpq_poly_init(Tq);fmpz_poly_t S,T;fmpz_poly_init(S);fmpz_poly_init(T);fmpz_t bezden,sd,td,scale;fmpz_init(bezden);fmpz_init(sd);fmpz_init(td);fmpz_init(scale);
 if(sj>=0){fmpq_poly_set_fmpz_poly(entryq,fmpz_poly_mat_entry(X,si,sj));fmpq_poly_set_fmpz_poly(Rq,R);fmpq_poly_gcd(Gq,entryq,Rq);gcd1=fmpq_poly_is_one(Gq);assert(gcd1);{ofstream ck(argv[4]);ck<<"{\"candidate_row\":"<<si<<",\"candidate_Bcolumn\":"<<sj<<",\"gcd_is1\":true,\"entry\":";jp(ck,fmpz_poly_mat_entry(X,si,sj));ck<<"}\n";}tick();fmpq_poly_xgcd(Gq,Sq,Tq,entryq,Rq);assert(fmpq_poly_is_one(Gq));fmpq_poly_get_denominator(sd,Sq);fmpq_poly_get_denominator(td,Tq);fmpz_lcm(bezden,sd,td);fmpq_poly_get_numerator(S,Sq);fmpq_poly_get_numerator(T,Tq);fmpz_divexact(scale,bezden,sd);fmpz_poly_scalar_mul_fmpz(S,S,scale);fmpz_divexact(scale,bezden,td);fmpz_poly_scalar_mul_fmpz(T,T,scale);fmpz_poly_t p0,p1;fmpz_poly_init(p0);fmpz_poly_init(p1);fmpz_poly_mul(p0,S,fmpz_poly_mat_entry(X,si,sj));fmpz_poly_mul(p1,T,R);fmpz_poly_add(p0,p0,p1);assert(fmpz_poly_degree(p0)==0&&fmpz_equal(p0->coeffs,bezden));fmpz_poly_clear(p0);fmpz_poly_clear(p1);long vectorbytes=decimal_bytes(den)+4096;for(int i=0;i<17;i++)vectorbytes+=decimal_bytes(fmpz_poly_mat_entry(X,i,sj));bezsaved=decimal_bytes(S)+decimal_bytes(T)+fmpz_sizeinbase(bezden,10)+vectorbytes<json_limit;}
 ofstream o(argv[2]);o<<"{\"solver_denominator\":";jp(o,den);char*r=fmpq_get_str(nullptr,10,ratio);o<<",\"solver_denominator_over_expected_QQunit\":\""<<r<<"\",\"all119_AX_equalities_checked\":true,\"all119_coefficient_slots\":"<<totalcoeff<<",\"selected_row\":"<<si<<",\"selected_Bcolumn\":"<<sj<<",\"selected17_vector\":[";if(sj>=0)for(int i=0;i<17;i++){if(i)o<<',';jp(o,fmpz_poly_mat_entry(X,i,sj));}o<<"],\"gcd_is_QQunit\":"<<(gcd1?"true":"false")<<",\"all119_divisible_R46\":"<<(sj<0?"true":"false")<<",\"Bezout_saved\":"<<(bezsaved?"true":"false");flint_free(r);if(bezsaved){o<<",\"Bezout_S_integer\":";jp(o,S);o<<",\"Bezout_T_integer\":";jp(o,T);char*bs=fmpz_get_str(nullptr,10,bezden);o<<",\"Bezout_nonzero_integer_constant\":\""<<bs<<'"';flint_free(bs);}o<<",\"native_seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-started).count()<<"}\n";
 fmpz_poly_clear(q);fmpz_poly_clear(rhs);fmpq_clear(ratio);fmpz_clear(dlead);fmpz_clear(elead);fmpq_poly_clear(qden);fmpq_poly_clear(qexpected);fmpq_poly_clear(qcheck);fmpq_poly_clear(entryq);fmpq_poly_clear(Rq);fmpq_poly_clear(Gq);fmpq_poly_clear(Sq);fmpq_poly_clear(Tq);fmpz_poly_clear(S);fmpz_poly_clear(T);fmpz_clear(bezden);fmpz_clear(sd);fmpz_clear(td);fmpz_clear(scale);fmpz_poly_clear(expected);fmpz_poly_clear(R);fmpz_poly_clear(den);fmpz_poly_mat_clear(A);fmpz_poly_mat_clear(B);fmpz_poly_mat_clear(X);fmpz_poly_mat_clear(check);flint_cleanup();}
